"""Markdown report generated from the results dict (every table in the README is copied from here)."""

from __future__ import annotations

from .ope import ESTIMATORS


def _table(header: list[str], rows: list[list[str]]) -> str:
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    out += ["| " + " | ".join(r) + " |" for r in rows]
    return "\n".join(out)


def render(res: dict) -> str:
    off, o = res["offline"], res["ope"]
    d = off["dataset"]
    lines = [
        "# Day 24 results report (generated by `make run`)",
        "",
        f"Data path: **{res['data']['path_used']}** ({res['data']['label']}). MovieLens attempt: `{res['data'].get('movielens_attempt', 'n/a')}`.",
        f"Scale: {d['n_users']:,} users x {d['n_items']:,} titles, {d['n_interactions']:,} watch events (density {100 * d['density']:.2f}%). Split: {d['split']}.",
        "",
        "## Offline test metrics (models refit on train+validation)",
        "",
    ]
    rows = []
    for name, m in off["test"].items():
        rows.append(
            [
                name,
                f"{m['ndcg@10']:.4f}",
                f"{m['recall@10']:.4f}",
                f"{m['recall@50']:.4f}",
                f"{100 * m['coverage@10']:.1f}%",
                f"{m['novelty@10']:.2f}",
                f"{100 * m['head_share@10']:.1f}%",
                f"{m['arp@10']:.0f}",
                f"{m['ild@10']:.3f}",
            ]
        )
    ref = off["test_reference"]
    rows.append(
        ["*Next titles users actually watched*", "", "", "", "", f"{ref['novelty']:.2f}", f"{100 * ref['head_share']:.1f}%", f"{ref['arp']:.0f}", ""]
    )
    lines.append(_table(["Model", "NDCG@10", "Recall@10", "Recall@50", "Coverage@10", "Novelty (bits)", "Head share@10", "ARP@10", "ILD@10"], rows))
    lines.append("")
    for key, label in (
        ("ndcg10_rerank_minus_als", "two-tower + re-ranker"),
        ("ndcg10_rerank_als_feature_minus_als", "two-tower + re-ranker (+ALS feature)"),
    ):
        diff = off[key]
        lines.append(
            f"- NDCG@10, {label} minus ALS: **{diff['mean']:+.4f}** (paired bootstrap 95% CI {diff['ci95'][0]:+.4f} to {diff['ci95'][1]:+.4f}, "
            f"{diff['bootstrap']} resamples; relative {100 * diff['relative_lift']:+.1f}%)."
        )
    v = off["validation"]
    lines += [
        "",
        f"ALS selected on validation NDCG@10 from {len(v['als_grid_ndcg@10'])} configurations: `{v['als_selected']}`.",
        "",
        "Re-ranker objective chosen on held-out validation users (NDCG@10): "
        + ", ".join(f"{k} {val:.4f}" for k, val in v["reranker_objective_ndcg@10_heldout_users"].items())
        + f" -> **{v['reranker_objective']}**.",
        "",
        "## Retrieval and serving",
        "",
    ]
    r, lat = off["retrieval"], off["latency"]
    lines.append(
        _table(
            ["Quantity", "Value"],
            [
                ["Candidate recall@100 (HNSW, test)", f"{r['candidate_recall@100']:.4f}"],
                ["HNSW recall@100 vs exact search", f"{r['hnsw_recall@100_vs_exact']:.4f}"],
                ["HNSW build time", f"{r['hnsw_build_seconds']:.2f} s"],
                [
                    "Latency p50 / p95 / p99, HNSW (user tower + top-100)",
                    f"{lat['hnsw']['end_to_end']['p50_ms']:.3f} / {lat['hnsw']['end_to_end']['p95_ms']:.3f} / {lat['hnsw']['end_to_end']['p99_ms']:.3f} ms",
                ],
                ["  of which ANN search p99", f"{lat['hnsw']['ann_search']['p99_ms']:.3f} ms"],
                ["  of which user tower p99", f"{lat['hnsw']['user_tower']['p99_ms']:.3f} ms"],
                ["Latency p99, exact flat index", f"{lat['exact_flat']['end_to_end']['p99_ms']:.3f} ms"],
                ["Requests timed", str(lat["hnsw"]["n_requests"])],
            ],
        )
    )
    lines += ["", "## Re-ranker feature importance (gain share)", ""]
    imp = off["reranker"]["feature_importance_gain"]
    lines.append(_table(["Feature", "Gain share"], [[k, f"{100 * v:.1f}%"] for k, v in sorted(imp.items(), key=lambda kv: -kv[1])]))
    lines += ["", "## MMR diversity re-ranking (stretch)", ""]
    lines.append(
        _table(
            ["lambda", "NDCG@10", "ILD@10", "Coverage@10", "Head share@10"],
            [
                [k, f"{m['ndcg@10']:.4f}", f"{m['ild@10']:.3f}", f"{100 * m['coverage@10']:.1f}%", f"{100 * m['head_share@10']:.1f}%"]
                for k, m in off["mmr"].items()
            ],
        )
    )

    s = o["setting"]
    lines += [
        "",
        "## Off-policy evaluation (SYNTHETIC world with known truth)",
        "",
        f"{s['n_users']:,} users, slate of {s['slate_size']} eligible titles each, logging policy {s['logging_policy']} (min propensity {s['min_propensity']:.4f}). "
        f"{s['n_replicates']} independent logs of {s['n_rounds']:,} rounds. Reward model: {s['reward_model']}.",
        "",
    ]
    rows = []
    for name, row in o["estimators"].items():
        cells = [name, f"{row['truth']:.4f}"]
        for e in ESTIMATORS:
            cells.append(f"{row[e]['bias']:+.4f} / {row[e]['std']:.4f} / {row[e]['rmse']:.4f}")
        cells += [o["closest_estimator_by_rmse"][name], f"{row['mean_ess']:.0f}"]
        rows.append(cells)
    lines.append(_table(["Target policy", "True play rate", *[f"{e} bias / std / RMSE" for e in ESTIMATORS], "Closest", "Mean ESS"], rows))
    lines += [
        "",
        f"Reference true play rates: logging policy {o['truth']['Logging policy (popularity)']:.4f}, oracle {o['truth']['Oracle (true best title)']:.4f}.",
        "",
        _table(
            ["Estimator", "Mean relative RMSE", "Mean Kendall tau vs true ranking", "Logs that pick the true best policy"],
            [
                [
                    e,
                    f"{100 * o['mean_relative_rmse'][e]:.2f}%",
                    f"{o['kendall_tau_vs_truth'][e]:.3f}",
                    f"{100 * o['share_of_logs_picking_true_best'][e]:.0f}%",
                ]
                for e in ESTIMATORS
            ],
        ),
        "",
        "### Relative RMSE vs log size (mean over policies)",
        "",
    ]
    sweep = o["rmse_vs_rounds"]
    rows = []
    for n, per in sweep.items():
        rows.append([f"{int(n):,}", *[f"{100 * sum(per[p][e] / o['truth'][p] for p in per) / len(per):.2f}%" for e in ESTIMATORS]])
    lines.append(_table(["Rounds", *ESTIMATORS], rows))
    lines += [
        "",
        f"Runtime: {res['timings']['total_seconds']:.0f} s total (offline {res['timings']['offline_seconds']:.0f} s, OPE {res['timings']['ope_seconds']:.0f} s).",
        "",
    ]
    return "\n".join(lines)
